entries[314959] = { ["name"] = "Baked Voidfin", ["text"] = "2 sec cast\nReagents:\nAberrant Voidfin (8), Questionable Meat (3), Aromatic Fish Oil (3), Wild Flour (4)\nPrepare Baked Voidfin.\nDrop:\nN'Zoth's Cultists\n\n(5)\nUse: Restores 50769 health and 30769 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed.\n\nWhile well fed, increase movement speed by 20% while in a Vision of N'Zoth." }
entries[314960] = { ["name"] = "K'Bab", ["text"] = "2 sec cast\nReagents:\nQuestionable Meat (8), Malformed Gnasher (5), Aberrant Voidfin (3), Aromatic Fish Oil (3)\nPrepare K'Bab.\nDrop:\nN'Zoth's Cultists\n\n(5)\nUse: Restores 50769 health and 30769 mana over 20 sec. Must remain seated while eating.\n\nIf you spend at least 10 seconds eating, instantly restore 100 Sanity. (3 Min Cooldown)" }
entries[314961] = { ["name"] = "Dubious Delight", ["text"] = "2 sec cast\nReagents:\nQuestionable Meat (8), Aromatic Fish Oil (3), Wild Flour (3), Fresh Potato (4)\nPrepare Dubious Delight.\nDrop:\nN'Zoth's Cultists\n\n(5)\nUse: Restores 50769 health and 30769 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed.\n\nWhile well fed, reduce the duration of incoming crowd control effects by 20% while in a Vision of N'Zoth." }
entries[314962] = { ["name"] = "Ghastly Goulash", ["text"] = "2 sec cast\nReagents:\nQuestionable Meat (8), Aberrant Voidfin (5), Malformed Gnasher (3), Aromatic Fish Oil (3)\nPrepare Ghastly Goulash.\nDrop:\nN'Zoth's Cultists\n\n(5)\nUse: Restores 50769 health and 30769 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed.\n\nWhile well fed, regenerate 2% of your max health per sec while in a Vision of N'Zoth." }
entries[314963] = { ["name"] = "Grilled Gnasher", ["text"] = "2 sec cast\nReagents:\nMalformed Gnasher (8), Questionable Meat (3), Aromatic Fish Oil (3), Foosaka (4)\nPrepare Grilled Gnasher.\nDrop:\nN'Zoth's Cultists\n\n(5)\nUse: Restores 50769 health and 30769 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed.\n\nWhile well fed, you assume the form of a K'thir, reducing the range that enemies will attack you while in a Vision of N'Zoth for 10 min." }
